#ifndef I2C_DW_APB_ERROR_H_
#define I2C_DW_APB_ERROR_H_

#include "status/msft_module_id.h"


#define	I2C_DW_APB_ERROR(code)		ROT_ERROR (MSFT_MODULE_I2C_DW_APB, code)

/**
 * Error codes that can be generated by an I2C slave driver.
 */
enum {
	I2C_DW_APB_INVALID_ARGUMENT = I2C_DW_APB_ERROR (0x00),		/**< Input parameter is null or not valid. */
	I2C_DW_APB_NO_MEMORY = I2C_DW_APB_ERROR (0x01),				/**< Memory allocation failed. */
	I2C_DW_APB_HW_ERROR = I2C_DW_APB_ERROR (0x02),				/**< A generic HW error occurred. */
	I2C_DW_APB_MISSING_HANDLERS = I2C_DW_APB_ERROR (0x03),		/**< Required handlers were not set. */
	I2C_DW_APB_INVALID_CAPS_MASK = I2C_DW_APB_ERROR (0x04),		/**< An invalid capabilities mask has been set for the driver. */
	I2C_DW_APB_INVALID_CLOCK_VALUE = I2C_DW_APB_ERROR (0x05),	/**< An invalid value was specified for a clock related parameter. */
	I2C_DW_APB_INVALID_ADDRESS = I2C_DW_APB_ERROR (0x06),		/**< Input address was invalid or unsupported. */
	I2C_DW_APB_NOT_SUPPORTED = I2C_DW_APB_ERROR (0x07),			/**< The operation is not supported for the device. */
	I2C_DW_APB_INVALID_MODE = I2C_DW_APB_ERROR (0x08),			/**< The operation is not supported for the currently configured device mode. */
	I2C_DW_APB_DISCARDING_RX = I2C_DW_APB_ERROR (0x09),			/**< An Rx operation failed due to the transaction being discarded. */
	I2C_DW_APB_BUS_BUSY = I2C_DW_APB_ERROR (0x0A),				/**< Bus activity detected during HW disable; controller restored to slave mode. */
};


#endif	/* I2C_DW_APB_ERROR_H_ */
